(()=>{const D=SIS_3D_DATA,W=document.querySelector('#world'),A=document.querySelector('#agents'),Dtail=document.querySelector('#detail'),L=document.querySelector('#loop'),R=Object.fromEntries(D.rooms.map(x=>[x.id,x])),S=Object.fromEntries(D.agents.map(x=>[x.id,{...x}]));let selected=D.agents[0],loop=false,bots={};const pos=(id)=>{let s=S[id],r=R[s.room],e=bots[id];if(e){e.style.left=50+r.x*.9+'%';e.style.top=50+r.z*.72+'%';e.dataset.part=s.part||s.parts[0]}};D.rooms.forEach(r=>{let e=document.createElement('div');e.className='zone';e.style.cssText=`--c:${r.c};left:${50+r.x*.9}%;top:${50+r.z*.72}%`;e.innerHTML=`${r.label}<small>local zone</small>`;W.append(e)});function log(s){Dtail.insertAdjacentHTML('beforeend',`<small class=log>${s}</small>`)}function detail(){let s=S[selected.id];Dtail.innerHTML=`<strong>${selected.label}</strong><br>${selected.complaint}<br><small>${s.task} · ${R[s.room].label}</small><div class=choices>${D.rooms.map(r=>`<button data-room=${r.id}>${r.label}</button>`).join('')}</div><div class=choices>${selected.parts.map(p=>`<button data-part=${p}>${p}</button>`).join('')}<button data-transform>Transform body</button></div>`;Dtail.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>move(selected.id,b.dataset.room));Dtail.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{s.part=b.dataset.part;pos(selected.id);detail();log(`${selected.label} swapped to ${s.part}`)});let transform=Dtail.querySelector('[data-transform]');transform.onclick=()=>{let e=bots[selected.id];e.classList.remove('transforming');void e.offsetWidth;e.classList.add('transforming');setTimeout(()=>e.classList.remove('transforming'),900);log(`${selected.label} ran reversible transform`)}}function agents(){A.innerHTML='';D.agents.forEach(a=>{let s=S[a.id],b=document.createElement('button');b.className='agent'+(a.id===selected.id?' active':'');b.style.setProperty('--c',a.c);b.innerHTML=`<strong>${a.label}</strong><span>${a.role} · ${s.state||'working'}</span>`;b.onclick=()=>{selected=a;agents();detail();document.querySelectorAll('.robot').forEach(e=>e.classList.toggle('selected',e.dataset.id===a.id))};A.append(b)})}function move(id,room){S[id].room=room;S[id].state='moving';pos(id);agents();detail();log(`${S[id].label} moved to ${R[room].label}`);setTimeout(()=>{S[id].state='working';agents();detail()},700)}D.agents.forEach(a=>{let e=document.createElement('div');e.className='robot';e.dataset.id=a.id;e.style.setProperty('--c',a.c);e.innerHTML=`<div class=bubble>${a.complaint}</div><div class=label>${a.label}</div><i class=head></i><i class=torso></i><i class=part></i><i class="arm l"></i><i class="arm r"></i><i class="leg l"></i><i class="leg r"></i>`;e.onclick=()=>{selected=a;agents();detail();document.querySelectorAll('.robot').forEach(x=>x.classList.toggle('selected',x===e))};W.append(e);bots[a.id]=e;pos(a.id)});L.onclick=()=>{loop=!loop;L.textContent=loop?'Stop work loop':'Start work loop';L.setAttribute('aria-pressed',loop);if(loop)D.agents.forEach(a=>{S[a.id].state='working'});agents();detail()};setInterval(()=>{if(loop){let a=D.agents[Math.floor(Date.now()/3000)%D.agents.length],i=D.rooms.findIndex(r=>r.id===S[a.id].room);move(a.id,D.rooms[(i+1)%D.rooms.length].id)}},3000);agents();detail()})();